<script setup>
import { computed, inject, ref, watch, onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { navigation } from '../navigation'
import { thresholdMetrics, sensorThresholdMetrics, sensorThresholdUnit } from '../thresholds'
const clone = value => JSON.parse(JSON.stringify(value))
const route = useRoute(), store = inject('notifications'), dataApi = inject('dataApi')
const data = ref(structuredClone(dataApi.projectData))
const unsubscribe = dataApi.subscribeData(next => { data.value = structuredClone(next) }); onBeforeUnmount(unsubscribe)
const editor = ref('blocks'), sensorDraft = ref(clone(store.sensorRules.value))
const intervalDraft = ref(store.intervalMinutes.value)
const draft = ref(clone(store.rules.value)), soundDraft = ref(store.sound.value), notice = ref('')
const system = computed(() => route.meta.section)
const nav = computed(() => navigation.find(n => n.id === system.value))
const metrics = computed(() => thresholdMetrics.filter(m => system.value === 'dashboard' || m.system === system.value))
const supportsSensors = computed(() => ['dashboard', 'energy', 'water'].includes(system.value))
const sensors = computed(() => data.value.sensors.filter(s => system.value === 'dashboard' || s.system === system.value))
const sensor = id => data.value.sensors.find(s => s.id === id)
const scopedSensorRules = computed(() => sensorDraft.value.filter(r => sensors.value.some(s => s.id === r.sensorId)))
const format = value => Number.isFinite(value) ? value.toLocaleString('en-SG', {maximumFractionDigits:2}) : 'Unavailable'
const rule = id => draft.value.find(r => r.id === id)
const active = computed(() => store.active.value.filter(a => system.value === 'dashboard' || a.system === system.value))
watch(system, () => { sensorDraft.value = clone(store.sensorRules.value); editor.value = 'blocks'; draft.value = clone(store.rules.value); soundDraft.value = store.sound.value; intervalDraft.value = store.intervalMinutes.value; notice.value = ''; store.error.value = '' })
async function save() {
  const next = store.rules.value.map(r => metrics.value.some(m => m.id === r.id) ? clone(rule(r.id)) : clone(r))
  if (soundDraft.value) await store.enableAudio()
  const otherRules = store.sensorRules.value.filter(r => !sensors.value.some(s => s.id === r.sensorId))
  notice.value = store.save(next, soundDraft.value, [...clone(otherRules), ...clone(scopedSensorRules.value)], intervalDraft.value) ? 'Thresholds saved. Current readings have been checked.' : ''
}
async function test() { if (soundDraft.value) { await store.enableAudio(); const old = store.sound.value; store.sound.value = true; await store.testAlert(system.value); store.sound.value = old } else await store.testAlert(system.value) }
function reset() { draft.value = clone(store.rules.value); sensorDraft.value = clone(store.sensorRules.value); soundDraft.value = store.sound.value; intervalDraft.value = store.intervalMinutes.value; notice.value = ''; store.error.value = '' }
function changeSensorMetric(r) { const s = sensor(r.sensorId); r.limit = r.metric === 'rate' ? s.expectedMaxRate : r.metric === 'today' ? Math.ceil(s.today * 1.2) : 0; r.direction = 'above' }
function addSensorRule() {
  for (const s of sensors.value) for (const m of sensorThresholdMetrics) {
    if (sensorDraft.value.some(r => r.sensorId === s.id && r.metric === m.id)) continue
    const r = { id: 'sensor-' + crypto.randomUUID(), sensorId: s.id, metric: m.id, enabled: true, limit: 0, direction: 'above' }
    changeSensorMetric(r); sensorDraft.value.push(r); notice.value = ''; return
  }
}
const canAdd = computed(() => sensors.value.length * sensorThresholdMetrics.length > scopedSensorRules.value.length)
const enabledCount = computed(() => metrics.value.filter(m => rule(m.id).enabled).length + scopedSensorRules.value.filter(r => r.enabled).length)
const dirty = computed(() => JSON.stringify(draft.value) !== JSON.stringify(store.rules.value) || JSON.stringify(sensorDraft.value) !== JSON.stringify(store.sensorRules.value) || soundDraft.value !== store.sound.value || intervalDraft.value !== store.intervalMinutes.value)
</script>
<template>
  <main class="threshold-page">
    <div class="page-heading"><div><p class="eyebrow">SYSTEM ALERTS</p><h1>{{ nav.label }} thresholds</h1><p class="subtitle">Set alert limits, choose what to monitor and review current breaches.</p></div><RouterLink class="threshold-link" :to="nav.path"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i> Back to overview</RouterLink></div>
    <div class="threshold-overview"><div><i class="fa-solid fa-sliders" aria-hidden="true"></i><span><strong>{{ enabledCount }} enabled rules</strong><small>{{ supportsSensors ? 'Location and individual sensor monitoring' : 'Location monitoring' }}</small></span></div><div><i class="fa-regular fa-bell" aria-hidden="true"></i><span><strong>{{ active.length }} active breaches</strong><small>Based on current readings</small></span></div><span class="threshold-draft-state">{{ dirty ? 'Unsaved changes' : 'Settings saved locally' }}</span></div>
    <form @submit.prevent="save"><section class="card threshold-editor">
      <div class="threshold-editor-tabs" role="tablist" aria-label="Threshold scope"><button type="button" role="tab" id="blocks-tab" :aria-selected="editor === 'blocks'" aria-controls="blocks-panel" :class="{selected: editor === 'blocks'}" @click="editor = 'blocks'">Location thresholds <span>{{ metrics.length }}</span></button><button v-if="supportsSensors" type="button" role="tab" id="sensors-tab" :aria-selected="editor === 'sensors'" aria-controls="sensors-panel" :class="{selected: editor === 'sensors'}" @click="editor = 'sensors'">Sensor thresholds <span>{{ scopedSensorRules.length }}</span></button></div>
      <div v-if="editor === 'blocks'" id="blocks-panel" role="tabpanel" aria-labelledby="blocks-tab"><div class="threshold-editor-heading"><div><h2>Location alert limits</h2><p>Choose a location, comparison and limit. All locations are evaluated individually.</p></div></div><div class="threshold-row-head block-row"><span>Metric</span><span>Applies to</span><span>Alert when</span><span>Limit</span><span>Enabled</span></div>
        <div v-for="metric in metrics" :key="metric.id" class="threshold-setting-row block-row"><div class="threshold-metric-label"><strong>{{ metric.label }}</strong><small>{{ metric.unit }} · Location reading</small></div><label><span class="threshold-mobile-label">Location</span><select v-model="rule(metric.id).blockId" :aria-label="metric.label + ' block'"><option value="all">All locations (per location)</option><option v-for="b in data.blocks" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label><span class="threshold-mobile-label">Alert when</span><select v-model="rule(metric.id).direction" :aria-label="metric.label + ' comparison'"><option value="above">Above</option><option value="below">Below</option></select></label><label class="threshold-limit"><span class="threshold-mobile-label">Limit ({{ metric.unit }})</span><input v-model.number="rule(metric.id).limit" type="number" min="0" :max="metric.unit === '%' ? 100 : undefined" :step="['people', 'meters', 'alerts', 'cameras'].includes(metric.unit) ? 1 : 'any'" required :aria-label="metric.label + ' limit'"><span class="threshold-unit">{{ metric.unit }}</span></label><label class="threshold-toggle"><input v-model="rule(metric.id).enabled" type="checkbox" :aria-label="'Enable ' + metric.label + ' threshold'"><span class="threshold-switch" aria-hidden="true"></span><span class="threshold-mobile-label">Enabled</span></label></div>
      </div>
      <div v-else id="sensors-panel" role="tabpanel" aria-labelledby="sensors-tab"><div class="threshold-editor-heading"><div><h2>Individual sensor alert limits</h2><p>Monitor each meter separately. Usage rules skip offline or faulty readings.</p></div><button type="button" class="primary" :disabled="!canAdd" @click="addSensorRule"><i class="fa-solid fa-plus" aria-hidden="true"></i> Add sensor rule</button></div><div v-if="!scopedSensorRules.length" class="threshold-sensor-empty"><i class="fa-solid fa-gauge" aria-hidden="true"></i><h3>No sensor rules yet</h3><p>Add a rule to monitor usage, connectivity or reported faults.</p></div>
        <template v-else><div class="threshold-row-head sensor-row"><span>Sensor</span><span>Metric</span><span>Alert when</span><span>Limit</span><span>Enabled</span><span></span></div><div v-for="r in scopedSensorRules" :key="r.id" class="threshold-setting-row sensor-row"><label><span class="threshold-mobile-label">Sensor</span><select v-model="r.sensorId" aria-label="Sensor target" @change="changeSensorMetric(r)"><option v-for="s in sensors" :key="s.id" :value="s.id">{{ s.id }} · {{ s.name }}</option></select></label><label><span class="threshold-mobile-label">Metric</span><select v-model="r.metric" aria-label="Sensor metric" @change="changeSensorMetric(r)"><option v-for="m in sensorThresholdMetrics" :key="m.id" :value="m.id">{{ m.label }}</option></select></label><label><span class="threshold-mobile-label">Alert when</span><select v-model="r.direction" aria-label="Sensor comparison"><option value="above">Above</option><option value="below">Below</option></select></label><label class="threshold-limit"><span class="threshold-mobile-label">Limit</span><input v-model.number="r.limit" type="number" min="0" :max="['offline', 'fault'].includes(r.metric) ? 1 : undefined" :step="['offline', 'fault'].includes(r.metric) ? 1 : 'any'" required aria-label="Sensor limit"><span class="threshold-unit">{{ sensorThresholdUnit(r.metric, sensor(r.sensorId)) }}</span></label><label class="threshold-toggle"><input v-model="r.enabled" type="checkbox" aria-label="Enable sensor threshold"><span class="threshold-switch" aria-hidden="true"></span><span class="threshold-mobile-label">Enabled</span></label><button class="icon-button" type="button" aria-label="Remove sensor rule" @click="sensorDraft = sensorDraft.filter(item => item.id !== r.id)"><i class="fa-regular fa-trash-can" aria-hidden="true"></i></button></div></template><p class="threshold-editor-note">State metrics: 0 = connected / no reported fault; 1 = offline / reported fault. Use Above 0 to alert. Each sensor can have one rule per metric.</p>
      </div>
      <div class="threshold-editor-footer"><span>Strict comparisons · Equal to the limit does not trigger an alert</span><div><button type="button" @click="reset">Discard changes</button><button class="primary" type="submit">Save thresholds</button></div></div>
    </section><p v-if="store.error.value" role="alert" class="range-error">{{ store.error.value }}</p><p v-if="notice" role="status" class="notice">{{ notice }}</p></form>
    <section class="card threshold-delivery"><h2>Notification delivery</h2><p>Alerts appear in the notification bell. Sound preference applies to all systems.</p><div class="notification-interval-setting"><label>Repeat active alerts every <span><input v-model.number="intervalDraft" type="number" min="1" max="60" step="1" aria-label="Notification interval in minutes"> minutes</span></label><p>The first breach alerts immediately. If it remains active, reminders repeat at this interval. Refresh keeps the remaining time; recovered readings stop reminders.</p><small v-if="store.nextReminderAt.value">Next active reminder: {{ new Date(store.nextReminderAt.value).toLocaleTimeString('en-SG', {timeZone:'Asia/Singapore'}) }} SGT</small></div><div class="threshold-sound"><label class="threshold-toggle"><input v-model="soundDraft" type="checkbox" aria-label="Play notification sound (all systems)"><span class="threshold-switch" aria-hidden="true"></span> Play notification sound (all systems)</label><button @click="test"><i class="fa-solid fa-volume-high" aria-hidden="true"></i> Test notification</button><button @click="store.enableAudio">Activate sound for this session</button><button @click="store.enableBrowserAlerts">Enable desktop notifications</button></div><p class="range-availability">{{ store.audioReady.value ? 'Sound activated for this session.' : 'Sound requires activation after opening or refreshing the workspace.' }} Desktop alerts: {{ store.browserAlerts.value ? 'enabled for this session' : 'off' }}. Save thresholds to keep your sound and reminder settings.</p><details><summary>How monitoring works</summary><p>Monitoring runs while this workspace is open. Rules start disabled; suggested limits are demo examples. Day-to-date consumption is cumulative. Active breaches repeat at the saved interval. Each breach keeps its own timer across refreshes. Recovery stops reminders; re-crossing within the interval waits for the existing cooldown. Changing the interval recalculates the next reminder from the most recent alert.</p></details></section>
    <section class="card threshold-active"><h2>Active threshold breaches <span class="tag">{{ active.length }}</span></h2><p v-if="!active.length" class="range-availability">No enabled thresholds are currently breached.</p><ul v-else><li v-for="a in active" :key="a.key"><strong>{{ a.sensorId ? a.sensorName + ' (' + a.sensorId + ')' : a.block }} · {{ a.metric }}</strong><span>{{ a.value }} {{ a.unit }} — {{ a.direction }} {{ a.limit }} {{ a.unit }}</span></li></ul></section>
  </main>
</template>
